import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import { ResultData } from './resultdata';
import { Constants } from './constants';
import { Article } from './article';

@Injectable({
  providedIn: 'root'
})
export class ArticleService {

  constructor(private httpClient: HttpClient) { }

  getArticles(): Observable<ResultData<Article[]>> {
    //http://localhost:8888/nafresh/api/index.php?entity=article&method=getall&params=
    return this.httpClient.get<ResultData<Article[]>>('https://djstechnologies.fr/nafresh/api/index.php?entity=article&method=getall&params=',Constants.HTTP_OPTIONS);
  }
}
